// The identity op against the Python reference in testdata/golden
// (generated by tools/golden/generate.py).
#include <algorithm>

#include "golden_assert.h"
#include "lineover/engine.h"
#include "lo_test.h"
#include "npy_io.h"
#include "png_io.h"

using namespace lo::testing;

LO_TEST(identity_u8_matches_python_reference) {
    const ImageU8 input = readPng(goldenPath("input/pattern_rgba8.png"));
    const ImageU8 expected = readPng(goldenPath("identity/expected_rgba8.png"));
    LO_CHECK(input.width == 64 && input.height == 48 && input.channels == 4);

    ImageU8 actual = input;
    std::fill(actual.data.begin(), actual.data.end(), std::uint8_t{0});
    lo::ops::identity(input.data.data(), actual.data.data(), input.data.size());

    LO_CHECK_GOLDEN(compareGolden(actual, expected, "identity_rgba8", kToleranceU8));
}

LO_TEST(identity_f32_matches_python_reference) {
    const ImageF32 input = readNpyF32(goldenPath("input/pattern_rec2020_f32.npy"));
    const ImageF32 expected = readNpyF32(goldenPath("identity/expected_rec2020_f32.npy"));
    LO_CHECK(input.width == 64 && input.height == 48 && input.channels == 4);

    ImageF32 actual = input;
    std::fill(actual.data.begin(), actual.data.end(), 0.0f);
    lo::ops::identity(input.data.data(), actual.data.data(), input.data.size());

    LO_CHECK_GOLDEN(compareGolden(actual, expected, "identity_rec2020_f32", kToleranceFloat));
}

// The PNG decoder is checked against Python too: the float reference of the 8-bit
// pattern (value / 255) must equal the decoded PNG.
LO_TEST(png_decoder_matches_python_decoding) {
    const ImageU8 decoded = readPng(goldenPath("input/pattern_rgba8.png"));
    const ImageF32 reference = readNpyF32(goldenPath("input/pattern_rgba8_as_f32.npy"));

    ImageF32 asFloat{decoded.width, decoded.height, decoded.channels, {}};
    asFloat.data.reserve(decoded.data.size());
    for (const std::uint8_t sample : decoded.data) asFloat.data.push_back(static_cast<float>(sample) / 255.0f);

    LO_CHECK_GOLDEN(compareGolden(asFloat, reference, "png_decoder_vs_python", Tolerance{1e-6, 1e-6}));
}

int main() { return lo::testing::runAllTests(); }
